// Func014_12_00 is a deterministically generated function
// for the repomap perf fixture; it references Func015_13_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func014_12_00(a, b int) int {
	if a > b {
		return Func015_13_00(a, b) + a
	}
	return Func015_13_00(b, a) - b
}

